/** Fault injection is confined to owned verification samples, never normal HTTP. */
public final class PaymentClosingCommands {
 private static final ObjectMapper JSON=new ObjectMapper();private static String id(){return UUID.randomUUID().toString();}
 public static final class Probe implements ITradePort {
  final CloseCommands.Sim delegate=new CloseCommands.Sim();boolean offline;
  public TradeReply execute(TradeDispatch d){if(offline)throw new OrderFailure(503,"OWNED_A_OFFLINE");var r=delegate.execute(d);if(d.method().equals("reserve")&&r.evidence()!=null){var e=CloseCommands.change(r.evidence(),"reservedAt",PaymentService.time(System.currentTimeMillis()-5000));delegate.records.put(d.order().orderId(),e);return new TradeReply(r.code(),e);}return r;}
  public TeamView team(String u,String t,String r){return delegate.team(u,t,r);}
 }
 @Configuration(proxyBeanMethods=false) public static class Config {@Bean @Primary Probe closingProbe(){return new Probe();}}
 private static final class FaultChannel implements IChannelClosing {
  final IChannelClosing original;boolean unavailable,lost,corrupt;
  FaultChannel(IChannelClosing original){this.original=original;}
  public ChannelClosure queryClose(PaymentClose r){if(unavailable)throw new IllegalStateException("owned close unknown");return original.queryClose(r);}
  public ChannelClosure closeRoot(PaymentClose r){var x=original.closeRoot(r);if(corrupt)return new ChannelClosure(r,x.gate(),x.closedAt(),List.of(),null);if(lost){lost=false;throw new IllegalStateException("owned lost close response");}return x;}
 }
 private static long count(JdbcTemplate db,String sql,Object...args){return db.queryForObject(sql,Long.class,args);}
 private static void held(JdbcTemplate db,String order){check(count(db,"SELECT COUNT(*) FROM b_inventory_reservation WHERE order_id=? AND state='HELD'",order)==1&&count(db,"SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",order)==1&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind IN ('RELEASE','CONFIRM')",order)==0,"unknown/paid retains HELD/guard with no release or fulfilment");}
 private static void due(JdbcTemplate db,String order){db.update("UPDATE b_trade_coordination SET next_attempt_ms=0,lease_until_ms=IF(lease_token IS NULL,NULL,0) WHERE order_id=?",order);}
 public static int run(String mode){try{
  check(Set.of("verify","recover").contains(mode)&&env("B_DATABASE_SCOPE").equals("b02-test")&&env("B_DATABASE_USERNAME").equals("zj_market_b02_test_app"),"isolated close verification");Path work=Path.of(env("B_PAYMENT_WORK"));
  try(var ctx=new SpringApplication(Config.class,OrderCommands.ProbeConfiguration.class,ZjMarketApplication.class).run("--server.port=0","--b.identity.enabled=true","--b.product.enabled=true","--b.inventory.enabled=true","--b.order.enabled=true","--b.trade.enabled=true","--b.trade.scheduler-enabled=false","--b.payment.enabled=true","--b.payment.checkout-enabled="+mode.equals("verify"),"--b.payment.scheduler-enabled=false","--b.trade.events-enabled=false","--b.trial.enabled=false","--b.sync.enabled=false","--b.infrastructure.database.enabled=true","--b.infrastructure.rpc.enabled=false","--b.infrastructure.mq.enabled=false")){
   var ds=ctx.getBean(DataSource.class);var db=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);var orders=ctx.getBean(IOrderRepository.class);var trade=ctx.getBean(TradeRepository.class);var pay=ctx.getBean(IPaymentRepository.class);var payments=ctx.getBean(IPaymentService.class);var simulator=ctx.getBean(ISimulatedChannel.class);var facts=(IChannelFacts)simulator;var fault=new FaultChannel((IChannelClosing)simulator);var settlement=new SettlementRepository(ds,tx,orders,"zj-market","s01","c01");var closing=new PaymentClosingRepository(ds,tx,orders,fault,settlement);trade.enablePaymentClosing(closing);var worker=ctx.getBean(ITradeCoordinationService.class);var life=ctx.getBean(IOrderLifecycleService.class);var probe=ctx.getBean(Probe.class);
   if(mode.equals("recover")){var f=JSON.readTree(Files.readAllBytes(work.resolve("restart.json")));String actor=f.path("actor").asText(),order=f.path("order").asText(),payment=f.path("payment").asText();var o=orders.byId(actor,order);probe.delegate.records.put(order,o.evidence());due(db,order);worker.recover(order);check(count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_request IS NOT NULL",order)==1,"new JVM freezes original root proof without checkout");held(db,order);due(db,order);worker.recover(order);check(orders.byId(actor,order).businessStatus().equals("CLOSED"),"new JVM confirms A cancelled");check(count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",order)==1,"one release after restart");check(f.path("closeId").asText().equals(db.queryForObject("SELECT channel_close_id FROM b_payment WHERE payment_id=?",String.class,payment)),"original close ID across JVM");Files.writeString(work.resolve("recover.txt"),"status=PASSED\nnew-JVM/checkout-disabled/committed-root-lost-response/original-closeId/A-query/one-release=PASSED\n");return 0;}
   var identity=ctx.getBean(IIdentityService.class);String suffix=id().substring(0,8),password="Closing-"+id();var u=identity.register("pcl"+suffix,password,"closing user");var v=identity.register("pcv"+suffix,password,"other user");var op=identity.initializeOperator("pco"+suffix,password,"closing operator");String actor=u.userId();var http=new Client("http://127.0.0.1:"+((WebServerApplicationContext)ctx).getWebServer().getPort(),env("B_IDENTITY_ORIGIN"));String jwt=http.login("pcl"+suffix,password),other=http.login("pcv"+suffix,password);
   // Frozen create has not reached the channel: establish a full-root tombstone first.
   var o=PaymentCommands.fresh(ctx,actor,op.userId());var ac=payments.create(actor,o.orderId(),id(),null,id());String p=ac.receipt().paymentId(),a=ac.receipt().attemptId();var old=pay.claim(p);long n=pay.now();var e=probe.execute(new TradeDispatch(null,o,"query",id(),null)).evidence();var evidence=new Evidence(e,n,pay.now(),1000000,2000,2000,2000);var pp=pay.payment(actor,p);var aa=pay.attempt(p,a);
   var samples=new LinkedHashMap<String,Object>();var exposed=http.call("GET","/orders/"+o.orderId(),null,jwt,200);samples.put("exposed",exposed);check(exposed.path("data").path("canCancel").asBoolean(),"HTTP advertises exposed close intent");String key=id();var body=Map.of("operationId",key,"reason","owned closing");http.call("POST","/orders/"+o.orderId()+"/cancel",body,other,404);samples.put("closing",http.call("POST","/orders/"+o.orderId()+"/cancel",body,jwt,202));check(!pay.canDispatch(old),"Mclose invalidates old payment token");check(count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_request IS NULL",o.orderId())==1,"no premature A unpaid declaration");
   fault.unavailable=true;int calls=probe.delegate.closeCalls;for(int fail=0;fail<5;fail++){due(db,o.orderId());worker.recover(o.orderId());held(db,o.orderId());}check(count(db,"SELECT COUNT(*) FROM b_trade_coordination WHERE order_id=? AND failure_count=5 AND alerted=1 AND run_state='READY'",o.orderId())==1,"fifth unknown alerts and retains original automatic recovery");check(probe.delegate.closeCalls==calls&&count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_request IS NULL",o.orderId())==1,"unknown root sends no A close and releases nothing");fault.unavailable=false;due(db,o.orderId());worker.recover(o.orderId());held(db,o.orderId());check(pay.payment(actor,p).gate().equals("CLOSED_UNPAID"),"complete root close proof recorded before A close");String frozen=db.queryForObject("SELECT close_request_hash FROM b_market_order WHERE order_id=?",String.class,o.orderId());check(simulator.create(pp,aa,o,evidence).state().equals("CLOSED_UNPAID"),"late create sees persistent tombstone");try{simulator.choose(pp,aa,o,evidence,"SUCCEEDED");throw new IllegalStateException("check: late success must reject");}catch(OrderFailure expected){}
   pay.finish(old,new Channel(p,a,"OPEN","late","9.00","CNY",null));check(pay.payment(actor,p).gate().equals("CLOSED_UNPAID"),"stale completion cannot reopen");due(db,o.orderId());worker.recover(o.orderId());check(orders.byId(actor,o.orderId()).businessStatus().equals("CLOSED"),"A query CANCELLED finalizes exposed close");samples.put("closed",http.call("POST","/orders/"+o.orderId()+"/cancel",body,jwt,200));http.call("POST","/orders/"+o.orderId()+"/cancel",Map.of("operationId",key,"reason","changed"),jwt,409);check(frozen.equals(db.queryForObject("SELECT close_request_hash FROM b_market_order WHERE order_id=?",String.class,o.orderId()))&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",o.orderId())==1,"immutable A close and exactly one release");
   Files.writeString(work.resolve("http-contract-samples.json"),JSON.writeValueAsString(samples));
   // Already committed success wins even when M2/notification has not run.
   var paid=PaymentCommands.fresh(ctx,actor,op.userId());var pc=payments.create(actor,paid.orderId(),id(),null,id());payments.tick(100);payments.choose(actor,pc.receipt().paymentId(),pc.receipt().attemptId(),id(),"SUCCEEDED",id());payments.tick(100);check(pay.payment(actor,pc.receipt().paymentId()).fundsState().equals("UNKNOWN"),"success before M2");life.cancel(actor,paid.orderId(),id(),"cancel races paid");calls=probe.delegate.closeCalls;worker.recover(paid.orderId());check(pay.payment(actor,pc.receipt().paymentId()).fundsState().equals("SUCCEEDED")&&orders.byId(actor,paid.orderId()).businessStatus().equals("PAID_WAITING_A"),"paid root wins via original M2");check(probe.delegate.closeCalls==calls&&count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_request IS NULL",paid.orderId())==1&&count(db,"SELECT COUNT(*) FROM b_trade_outbox WHERE payment_id=?",pc.receipt().paymentId())==1&&count(db,"SELECT COUNT(*) FROM b_trade_work WHERE payment_id=? AND kind='REFUND_OBLIGATION'",pc.receipt().paymentId())==0,"paid winner no unpaid close or spurious refund; one original outbox");held(db,paid.orderId());
   // Actual parallel root close and already-in-flight channel choice, repeated on fresh orders.
   for(int i=0;i<8;i++){var race=PaymentCommands.fresh(ctx,actor,op.userId());var c=payments.create(actor,race.orderId(),id(),null,id());String rp=c.receipt().paymentId(),ra=c.receipt().attemptId();payments.tick(100);var payment=pay.payment(actor,rp);var attempt=pay.attempt(rp,ra);n=pay.now();e=probe.execute(new TradeDispatch(null,race,"query",id(),null)).evidence();var ev=new Evidence(e,n,pay.now(),1000000,2000,2000,2000);life.cancel(actor,race.orderId(),id(),"race root");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var close=pool.submit(()->worker.recover(race.orderId()));var choose=pool.submit(()->{try{simulator.choose(payment,attempt,race,ev,"SUCCEEDED");}catch(OrderFailure rejected){}});close.get();choose.get();}var observed=simulator.query(rp,ra);if(observed.state().equals("SUCCEEDED")){settlement.observe(facts.fact(rp,ra));check(pay.payment(actor,rp).fundsState().equals("SUCCEEDED")&&count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_request IS NULL",race.orderId())==1,"race paid winner");held(db,race.orderId());}else{check(observed.state().equals("CLOSED_UNPAID"),"race single terminal arbitration");due(db,race.orderId());worker.recover(race.orderId());check(orders.byId(actor,race.orderId()).businessStatus().equals("CLOSED")&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",race.orderId())==1,"race unpaid winner");}}
   // All attempts, including a definite failure followed by a pending retry, are covered.
   var multiple=PaymentCommands.fresh(ctx,actor,op.userId());var mc=payments.create(actor,multiple.orderId(),id(),null,id());payments.tick(100);payments.choose(actor,mc.receipt().paymentId(),mc.receipt().attemptId(),id(),"FAILED",id());payments.tick(100);var retry=payments.create(actor,multiple.orderId(),id(),mc.receipt().attemptId(),id());life.cancel(actor,multiple.orderId(),id(),"all attempts");worker.recover(multiple.orderId());String mp=mc.receipt().paymentId();check(count(db,"SELECT COUNT(*) FROM b_sim_attempt WHERE payment_id=?",mp)==2&&pay.attempt(mp,mc.receipt().attemptId()).state().equals("FAILED")&&pay.attempt(mp,retry.receipt().attemptId()).state().equals("CLOSED_UNPAID"),"full failed and not-yet-created retry coverage");
   var releaseLease=trade.claim(multiple.orderId(),30000);check(trade.prepare(releaseLease),"root proof ready before query");var dispatch=trade.beforeSend(releaseLease);var answer=probe.execute(dispatch);var broken=(TradeRepository)CloseCommands.faulty(ds,orders);broken.enablePaymentClosing(closing);try{broken.complete(dispatch,answer);throw new IllegalStateException("check: release fault expected");}catch(IllegalStateException expected){check(!expected.getMessage().startsWith("check:"),"owned release ledger failure injected");}held(db,multiple.orderId());check(orders.byId(actor,multiple.orderId()).businessStatus().equals("CLOSING"),"balance/order/reservation/ledger/guard/task rollback together");trade.complete(dispatch,answer);check(count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",multiple.orderId())==1,"retry release exactly once after rollback");
   // Valid root proof is frozen even if A is unavailable; retry must keep verifiedAt/hash.
   var offline=PaymentCommands.fresh(ctx,actor,op.userId());var oc=payments.create(actor,offline.orderId(),id(),null,id());life.cancel(actor,offline.orderId(),id(),"A offline after root proof");probe.offline=true;worker.recover(offline.orderId());held(db,offline.orderId());String oh=db.queryForObject("SELECT close_request_hash FROM b_market_order WHERE order_id=?",String.class,offline.orderId());Long verified=db.queryForObject("SELECT close_verified_at_ms FROM b_payment WHERE payment_id=?",Long.class,oc.receipt().paymentId());check(oh!=null&&verified!=null,"A outage keeps immutable proof and original declaration");probe.offline=false;for(int i=0;i<3;i++){due(db,offline.orderId());worker.recover(offline.orderId());}check(orders.byId(actor,offline.orderId()).businessStatus().equals("CLOSED")&&oh.equals(db.queryForObject("SELECT close_request_hash FROM b_market_order WHERE order_id=?",String.class,offline.orderId()))&&verified.equals(db.queryForObject("SELECT close_verified_at_ms FROM b_payment WHERE payment_id=?",Long.class,oc.receipt().paymentId())),"A outage recovers same closeId/body/first verifiedAt");
   // Timeout reason is obtained from a fresh A query after the actual owned window expires.
   probe.delegate.reserveLifetime=8000;var timeout=PaymentCommands.fresh(ctx,actor,op.userId());probe.delegate.reserveLifetime=900000;var tc=payments.create(actor,timeout.orderId(),id(),null,id());payments.tick(100);long remaining=pay.payment(actor,tc.receipt().paymentId()).paymentDeadline()-pay.now()+20;if(remaining>0)Thread.sleep(remaining);worker.recover(timeout.orderId());check(orders.byId(actor,timeout.orderId()).businessStatus().equals("CLOSING")&&count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_reason IS NULL AND close_request IS NULL",timeout.orderId())==1,"fresh expired A evidence precedes timeout channel closing");check(JSON.readTree(db.queryForObject("SELECT CONVERT(channel_close_request USING utf8mb4) FROM b_payment WHERE payment_id=?",String.class,tc.receipt().paymentId())).path("reason").asText().equals("PAYMENT_TIMEOUT"),"timeout reason frozen in root request before A declaration");worker.recover(timeout.orderId());held(db,timeout.orderId());worker.recover(timeout.orderId());check(orders.byId(actor,timeout.orderId()).businessStatus().equals("CLOSED"),"timeout exposed close completes only after A CANCELLED query");
   // Old NEVER_OPENED declaration never changes, and cannot reopen payments.
   var legacy=PaymentCommands.fresh(ctx,actor,op.userId());life.cancel(actor,legacy.orderId(),id(),"legacy never opened");String lh=db.queryForObject("SELECT close_request_hash FROM b_market_order WHERE order_id=?",String.class,legacy.orderId());check(!payments.create(actor,legacy.orderId(),id(),null,id()).receipt().accepted(),"frozen legacy close rejects before channel exposure");worker.recover(legacy.orderId());worker.recover(legacy.orderId());check(orders.byId(actor,legacy.orderId()).businessStatus().equals("CLOSED")&&lh.equals(db.queryForObject("SELECT close_request_hash FROM b_market_order WHERE order_id=?",String.class,legacy.orderId()))&&pay.forOrder(actor,legacy.orderId())==null,"legacy frozen close unchanged and permanently blocks opening");
   // A contradictory/truncated proof is durable review, never an unpaid declaration.
   var corrupt=PaymentCommands.fresh(ctx,actor,op.userId());var cc=payments.create(actor,corrupt.orderId(),id(),null,id());life.cancel(actor,corrupt.orderId(),id(),"owned invalid proof");fault.corrupt=true;calls=probe.delegate.closeCalls;worker.recover(corrupt.orderId());fault.corrupt=false;held(db,corrupt.orderId());check(orders.byId(actor,corrupt.orderId()).reviewRequired()&&count(db,"SELECT COUNT(*) FROM b_trade_quarantine WHERE receipt_key=? AND reason='CHANNEL_CLOSE_CONFLICT'",db.queryForObject("SELECT channel_close_id FROM b_payment WHERE payment_id=?",String.class,cc.receipt().paymentId()))==1&&count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_request IS NULL",corrupt.orderId())==1&&probe.delegate.closeCalls==calls,"invalid full-root proof quarantined before A close");
   // Old A query lease must not overwrite the new Mclose intent.
   var stale=PaymentCommands.fresh(ctx,actor,op.userId());var sc=payments.create(actor,stale.orderId(),id(),null,id());db.update("UPDATE b_trade_coordination SET intent='QUERY',intent_version=intent_version+1,run_state='READY',next_attempt_ms=0 WHERE order_id=?",stale.orderId());var staleDispatch=trade.beforeSend(trade.claim(stale.orderId(),30000));var staleReply=probe.execute(staleDispatch);life.cancel(actor,stale.orderId(),id(),"invalidate old A query");check(!trade.complete(staleDispatch,staleReply)&&orders.byId(actor,stale.orderId()).businessStatus().equals("CLOSING"),"old A completion fenced by new close intent");worker.recover(stale.orderId());worker.recover(stale.orderId());check(orders.byId(actor,stale.orderId()).businessStatus().equals("CLOSED"),"new close intent survives old A worker");
   // Channel commit followed by response loss: leave original root for a real second JVM.
   var restart=PaymentCommands.fresh(ctx,actor,op.userId());var rc=payments.create(actor,restart.orderId(),id(),null,id());life.cancel(actor,restart.orderId(),id(),"restart lost close");fault.lost=true;worker.recover(restart.orderId());held(db,restart.orderId());check(count(db,"SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_request IS NULL",restart.orderId())==1&&count(db,"SELECT COUNT(*) FROM b_sim_payment WHERE payment_id=? AND gate='CLOSED_UNPAID' AND close_result IS NOT NULL",rc.receipt().paymentId())==1,"independent channel commit survives response loss");
   Files.writeString(work.resolve("restart.json"),JSON.writeValueAsString(Map.of("actor",actor,"order",restart.orderId(),"payment",rc.receipt().paymentId(),"closeId",db.queryForObject("SELECT channel_close_id FROM b_payment WHERE payment_id=?",String.class,rc.receipt().paymentId()))));Files.writeString(work.resolve("verify.txt"),"status=PASSED\nreal-MySQL/HTTP/root-tombstone/late-create/late-success/stale-payment-token=PASSED\nunknown-fifth-alert/unknown-no-A-close/HELD/guard/immutable-A-request/one-release=PASSED\npaid-before-M2/original-success-outbox/no-spurious-refund=PASSED\nparallel-root-arbitration-8-fresh-orders=PASSED\nfull-attempt-coverage/release-atomic-rollback/A-outage-frozen-verifiedAt/actual-expiry-timeout/legacy-frozen-close=PASSED\ninvalid-proof-durable-quarantine/old-A-query-lease-fenced=PASSED\nindependent-close-response-loss/new-JVM=PREPARED\n");return 0;
  }
 }catch(Exception e){System.err.println("Payment closing verification failed: "+e.getClass().getSimpleName()+" "+(e.getMessage()!=null&&e.getMessage().startsWith("check:")?e.getMessage():"details withheld"));try{Files.writeString(Path.of(env("B_PAYMENT_WORK")).resolve("failure.txt"),e.toString()+"\n"+String.valueOf(e.getCause()));}catch(Exception ignored){}return 1;}}
}
